"use client"

import { useLayoutEffect, useRef, useState } from "react"
import * as m from "motion/react-m"

// The sidebar remounts on every navigation (each page renders its own
// MainLayout), so the last position lives at module level. This gives the
// "slides between items" effect without layoutId (which would need domMax).
const lastY: Record<string, number | undefined> = {}

export function SidebarIndicator({ activeKey, variant }: { activeKey: string | null; variant: string }) {
  // A hidden probe gives us the <nav> (its parent) inside our own layout effect:
  // a parent's ref is not attached yet when a child's layout effect runs.
  const probe = useRef<HTMLSpanElement>(null)
  const [pos, setPos] = useState<{ y: number; fromY: number; h: number; x: number; w: number } | null>(null)

  useLayoutEffect(() => {
    const nav = probe.current?.parentElement
    if (!nav || !activeKey) { setPos(null); return }
    const el = nav.querySelector<HTMLElement>(`[data-nav-key="${CSS.escape(activeKey)}"]`)
    if (!el) { setPos(null); return }
    const y = el.offsetTop
    const fromY = lastY[variant] ?? y
    lastY[variant] = y
    setPos({ y, fromY, h: el.offsetHeight, x: el.offsetLeft, w: el.offsetWidth })
  }, [activeKey, variant])

  return (
    <>
    <span ref={probe} hidden />
    {pos && <m.div
      aria-hidden="true"
      className="pointer-events-none absolute left-0 top-0 z-0 rounded-lg bg-sidebar-primary shadow-sm"
      style={{ x: pos.x, width: pos.w, height: pos.h }}
      initial={{ y: pos.fromY }}
      animate={{ y: pos.y }}
      transition={{ type: "spring", stiffness: 520, damping: 42, mass: 0.8 }}
    />}
    </>
  )
}
