"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import Image from "next/image"
import {
  LayoutDashboard,
  Users,
  Contact,
  DollarSign,
  ShoppingBag,
  FileText,
  Receipt,
  Headphones,
  BarChart3,
  Settings,
  Calendar,
  Mail,
  Zap,
  Briefcase,
  Shield,
  HardHat,
  CalendarCheck,
  Wallet,
  Package,
  ReceiptText,
  Tags,
  Calculator,
  ClipboardList,
} from "lucide-react"
import { cn } from "@/lib/utils"
import { useAuthStore } from "@/lib/auth-store"
import { useI18n } from "@/lib/i18n"
import { SidebarIndicator } from "@/components/motion/sidebar-indicator"

const navigation = [
  { labelKey: "nav.dashboard", href: "/", icon: LayoutDashboard },
  { labelKey: "nav.myWork", href: "/my-work", icon: ClipboardList, selfOnly: true },
  { labelKey: "nav.leads", href: "/leads", icon: Users },
  { labelKey: "nav.contacts", href: "/contacts", icon: Contact },
  { labelKey: "nav.deals", href: "/pipeline", icon: DollarSign },
  { labelKey: "nav.accounts", href: "/clients", icon: ShoppingBag },
  { labelKey: "nav.products", href: "/products", icon: ShoppingBag },
  { labelKey: "nav.quotes", href: "/quotes", icon: FileText },
  { labelKey: "nav.invoices", href: "/invoices", icon: Receipt },
  { labelKey: "nav.projects", href: "/projects", icon: Briefcase },
  { section: "nav.section.accounting" },
  { labelKey: "nav.accounting", href: "/accounting", icon: Calculator },
  { labelKey: "nav.employees", href: "/employees", icon: HardHat },
  { labelKey: "nav.attendance", href: "/attendance", icon: CalendarCheck },
  { labelKey: "nav.payroll", href: "/admin/payroll", icon: Wallet },
  { labelKey: "nav.materials", href: "/materials", icon: Package },
  { labelKey: "nav.expenses", href: "/expenses", icon: ReceiptText },
  { labelKey: "nav.priceList", href: "/price-list", icon: Tags },
  { labelKey: "nav.reports", href: "/reports", icon: BarChart3 },
  { section: "nav.section.other" },
  { labelKey: "nav.cases", href: "/cases", icon: Headphones },
  { labelKey: "nav.complaints", href: "/complaints", icon: FileText },
  { labelKey: "nav.activities", href: "/activities", icon: Calendar },
  { labelKey: "nav.email", href: "/email", icon: Mail },
  { labelKey: "nav.automation", href: "/automation", icon: Zap },
  { labelKey: "nav.settings", href: "/settings", icon: Settings },
  { labelKey: "nav.userManagement", href: "/admin", icon: Shield, adminOnly: true },
] as { labelKey?: string; href?: string; icon?: any; section?: string; adminOnly?: boolean; selfOnly?: boolean }[]

// Pages for roles without finance access (empleado / worker / user)
const SELF_PAGES = ["/", "/my-work", "/projects", "/activities", "/settings", "/complaints"]

interface SidebarNavProps {
  onNavigate?: () => void
}

export function SidebarNav({ onNavigate }: SidebarNavProps) {
  const pathname = usePathname()
  const { user } = useAuthStore()
  const { t } = useI18n()
  const tfn = t

  const role = user?.role
  const isAdmin = role === "admin"
  const isStaff = isAdmin || role === "contador"
  const visible = navigation.filter((item) => {
    if (item.section) return isStaff
    if (item.adminOnly) return isAdmin
    if (!isStaff) return SELF_PAGES.includes(item.href!)
    if (item.selfOnly) return false
    return true
  })
  const allNavigation = visible.filter((item, i) => !item.section || (visible[i + 1] && !visible[i + 1].section))
  const activeHref = allNavigation.find((i) => i.href && i.href === pathname)?.href ?? null

  return (
    <aside className="flex h-full w-full flex-col border-r bg-sidebar text-sidebar-foreground">
      <div className="flex h-14 items-center justify-center border-b px-3 sm:h-16 sm:px-4">
        <Link href="/" className="flex items-center" onClick={onNavigate}>
          <Image src="/logo.png" alt="Paint Power" width={140} height={50} className="h-8 w-auto sm:h-10" priority />
        </Link>
      </div>

      <nav className="scrollbar-custom relative flex-1 space-y-0.5 overflow-y-auto overscroll-contain p-2 sm:p-3">
        <SidebarIndicator activeKey={activeHref} variant={onNavigate ? "sheet" : "desktop"} />
        {allNavigation.map((item) => {
          if (item.section) return <div key={item.section} className="px-3 pb-1 pt-3 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">{tfn(item.section)}</div>
          const Icon = item.icon
          const isActive = pathname === item.href
          return (
            <Link
              key={item.href}
              href={item.href!}
              onClick={onNavigate}
              data-nav-key={item.href}
              aria-current={isActive ? "page" : undefined}
              className={cn(
                "relative z-10 flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors",
                isActive
                  ? "font-semibold text-sidebar-primary-foreground"
                  : "text-muted-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
              )}
            >
              <Icon className="h-5 w-5 shrink-0" />
              <span className="truncate">{tfn(item.labelKey!)}</span>
            </Link>
          )
        })}
      </nav>
    </aside>
  )
}
