"use client"

import type React from "react"
import { useState, useEffect } from "react"
import { useRouter, usePathname } from "next/navigation"
import { SidebarNav } from "./sidebar-nav"
import { ThemeToggle } from "./theme-toggle"
import { LanguageToggle } from "./language-toggle"
import { useI18n } from "@/lib/i18n"
import {
  Search,
  Bell,
  HelpCircle,
  User,
  ChevronDown,
  LogOut,
  UserCircle,
  CreditCard,
  Menu,
  Settings,
} from "lucide-react"
import { Input } from "./ui/input"
import { Button } from "./ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "./ui/dropdown-menu"
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "./ui/sheet"
import { Badge } from "./ui/badge"
import { useDataStore, initializeDataStore } from "@/lib/data-store"
import { useAuthStore } from "@/lib/auth-store"
import { PageFade } from "@/components/motion/page-fade"

export function MainLayout({ children }: { children: React.ReactNode }) {
  const [showNotifications, setShowNotifications] = useState(false)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [searchQuery, setSearchQuery] = useState("")
  const router = useRouter()
  const pathname = usePathname()

  const { user, logout } = useAuthStore()
  const { notifications, markNotificationRead, markAllNotificationsRead } = useDataStore()
  const { t } = useI18n()

  const unreadCount = notifications.filter((n) => n.unread).length

  useEffect(() => {
    setMobileMenuOpen(false)
  }, [pathname])

  useEffect(() => {
    // Load initial data from the server-backed JSON database
    initializeDataStore()
  }, [])

  const handleNavigate = (path: string) => {
    router.push(path)
    setMobileMenuOpen(false)
  }

  const handleLogout = () => {
    logout()
    router.push("/login")
  }

  return (
    <div className="flex min-h-screen bg-background">
      <div className="hidden lg:block lg:fixed lg:left-0 lg:top-0 lg:z-40 lg:h-screen lg:w-64">
        <SidebarNav />
      </div>

      <Sheet open={mobileMenuOpen} onOpenChange={setMobileMenuOpen}>
        <SheetContent side="left" className="w-[280px] p-0">
          <SidebarNav onNavigate={() => setMobileMenuOpen(false)} />
        </SheetContent>
      </Sheet>

      <div className="flex flex-1 flex-col lg:ml-64">
        <header className="sticky top-0 z-30 border-b bg-card/95 backdrop-blur supports-[backdrop-filter]:bg-card/60">
          <div className="flex h-14 items-center gap-2 px-3 sm:h-16 sm:gap-4 sm:px-4 lg:px-6">
            <Button variant="ghost" size="icon" className="shrink-0 lg:hidden" onClick={() => setMobileMenuOpen(true)}>
              <Menu className="h-5 w-5" />
              <span className="sr-only">{t("header.openMenu")}</span>
            </Button>

            <div className="flex flex-1 items-center gap-2 sm:gap-4">
              <div className="relative w-full max-w-sm lg:max-w-md">
                <Search className="absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground sm:left-3" />
                <Input
                  placeholder={t("search.placeholder")}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="h-9 pl-8 pr-4 text-sm focus-visible:ring-primary sm:h-10 sm:pl-9"
                />
              </div>
            </div>

            <div className="flex items-center gap-1 sm:gap-2">
              <Button variant="ghost" size="icon" className="hidden shrink-0 sm:flex">
                <HelpCircle className="h-5 w-5" />
                <span className="sr-only">{t("header.help")}</span>
              </Button>

              <Button
                variant="ghost"
                size="icon"
                className="relative shrink-0"
                onClick={() => setShowNotifications(true)}
              >
                <Bell className="h-5 w-5" />
                {unreadCount > 0 && (
                  <Badge
                    variant="destructive"
                    className="absolute -right-1 -top-1 flex h-5 min-w-[1.25rem] items-center justify-center rounded-full px-1 text-[10px] font-semibold"
                  >
                    {unreadCount > 9 ? "9+" : unreadCount}
                  </Badge>
                )}
                <span className="sr-only">{t("header.notifications")}</span>
              </Button>

              <ThemeToggle />
              <LanguageToggle />

              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" className="gap-2 px-2 sm:px-3">
                    <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground">
                      <User className="h-4 w-4" />
                    </div>
                    <div className="hidden text-left xl:block">
                      <p className="text-sm font-medium leading-tight">{user?.name}</p>
                      <p className="text-xs text-muted-foreground leading-tight">{user?.email}</p>
                    </div>
                    <ChevronDown className="hidden h-4 w-4 sm:block" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuLabel>
                    <div className="flex flex-col space-y-1">
                      <p className="text-sm font-medium leading-none">{user?.name}</p>
                      <p className="text-xs leading-none text-muted-foreground">{user?.email}</p>
                    </div>
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => handleNavigate("/settings")}>
                    <UserCircle className="mr-2 h-4 w-4" />
                    {t("header.profile")}
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleNavigate("/settings")}>
                    <CreditCard className="mr-2 h-4 w-4" />
                    {t("header.billing")}
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => handleNavigate("/settings")}>
                    <Settings className="mr-2 h-4 w-4" />
                    {t("header.settings")}
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem className="text-destructive" onClick={handleLogout}>
                    <LogOut className="mr-2 h-4 w-4" />
                    {t("header.logout")}
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>
        </header>

        <main className="flex-1">
          <PageFade key={pathname}>{children}</PageFade>
        </main>
      </div>

      <Sheet open={showNotifications} onOpenChange={setShowNotifications}>
        <SheetContent className="w-full sm:max-w-md">
          <SheetHeader>
            <SheetTitle>{t("header.notificationsTitle")}</SheetTitle>
          </SheetHeader>
          <div className="mt-4 space-y-4">
            <div className="flex items-center justify-between">
              <p className="text-sm text-muted-foreground">
                {unreadCount === 0
                  ? t("notifications.none")
                  : t("notifications.count").replace("{{count}}", String(unreadCount))}
              </p>
              {unreadCount > 0 && (
                <Button variant="ghost" size="sm" onClick={markAllNotificationsRead} className="h-8 text-xs">
                  {t("notifications.markAllRead")}
                </Button>
              )}
            </div>

            <div className="space-y-3">
              {notifications.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-12 text-center">
                  <Bell className="h-12 w-12 text-muted-foreground/50 mb-2" />
                  <p className="text-sm text-muted-foreground">{t("notifications.empty")}</p>
                </div>
              ) : (
                notifications.map((notification) => (
                  <button
                    key={notification.id}
                    className="flex w-full gap-3 rounded-lg border p-3 text-left transition-colors hover:bg-accent active:scale-[0.98]"
                    onClick={() => markNotificationRead(notification.id)}
                  >
                    <div className="flex-1 space-y-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-sm font-medium leading-tight line-clamp-1">{notification.title}</p>
                        {notification.unread && (
                          <Badge variant="default" className="h-2 w-2 shrink-0 rounded-full p-0" />
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground line-clamp-2">{notification.description}</p>
                      <p className="text-xs text-muted-foreground">{notification.time}</p>
                    </div>
                  </button>
                ))
              )}
              
            </div>
          </div>
        </SheetContent>
      </Sheet>
    </div>
  )
}
