"use client"

import type React from "react"
import * as m from "motion/react-m"

/** 150 ms opacity-only fade for page content. Nothing moves. */
export function PageFade({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <m.div className={className} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15, ease: "easeOut" }}>
      {children}
    </m.div>
  )
}
